"use strict";(self.webpackChunknomos_docusaurus_template=self.webpackChunknomos_docusaurus_template||[]).push([[4650],{58910:(e,t,o)=>{o.r(t),o.d(t,{assets:()=>l,contentTitle:()=>r,default:()=>h,frontMatter:()=>s,metadata:()=>n,toc:()=>c});const n=JSON.parse('{"id":"index","title":"Vision","description":"Once again, the world stands at a crossroads. For as long as humanity has lived together, there have been individuals seeking to control others, and individuals seeking freedom from that control. As history marched onward, technologies emerged that shifted this struggle toward one side or the other. From writing, to gunpowder, to the printing press, to the revolver \u2013 inventions would periodically arise and upset the balance of forces in unpredictable ways. In recent times, the internet \u2013 initially hailed as a bastion for free speech and free association \u2013 has become a tool for mass surveillance and control.","source":"@site/about/index.md","sourceDirName":".","slug":"/","permalink":"/about/","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"title":"Vision","sidebar_position":1,"hide_table_of_contents":true},"sidebar":"defaultSidebar","next":{"title":"Description and Architecture","permalink":"/about/architect"}}');var i=o(74848),a=o(28453);const s={title:"Vision",sidebar_position:1,hide_table_of_contents:!0},r=void 0,l={},c=[];function d(e){const t={a:"a",p:"p",strong:"strong",...(0,a.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.p,{children:"Once again, the world stands at a crossroads. For as long as humanity has lived together, there have been individuals seeking to control others, and individuals seeking freedom from that control. As history marched onward, technologies emerged that shifted this struggle toward one side or the other. From writing, to gunpowder, to the printing press, to the revolver \u2013 inventions would periodically arise and upset the balance of forces in unpredictable ways. In recent times, the internet \u2013 initially hailed as a bastion for free speech and free association \u2013 has become a tool for mass surveillance and control."}),"\n",(0,i.jsx)(t.p,{children:"The ideological experiments of the 19th and 20th centuries have made it clear that political action alone will not bring lasting freedoms to the human race. Recognising this, the cypherpunk movement sought to proactively create technologies to ensure that civil liberties become inviolable by design. Among their most influential creations was Bitcoin which, along with the blockchain protocols it inspired, built the foundation for a financial system independent from state power and elite control. However, as the public nature of these blockchains exposed their participants to government scrutiny and regulation, that original vision was gradually replaced with arcane financial instruments and predatory speculation."}),"\n",(0,i.jsxs)(t.p,{children:["The ",(0,i.jsx)(t.a,{href:"https://logos.co/",children:"Logos movement"})," was founded as a revival of the cypherpunk ideal that has been all but forgotten over the past several decades. Logos has dedicated itself to the creation of decentralised technologies that would enable people to engage in social collaboration on their own terms \u2013 without being worried about censorship or coercion. These voluntary associations and institutions that function with an emergent order and are resistant to corruption are referred to as ",(0,i.jsx)(t.strong,{children:"network states"}),", in contrast to traditional states that rely on threats of violence to maintain control. Only with a technology stack that facilitates private and permissionless consensus, data storage, and communication can this vision be made a reality."]}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"Nomos"})," was created by Logos to be the infrastructure facilitating the creation of network states and enabling people to easily interact with them. Using Nomos, network states are implemented as lightweight blockchains known as Zones, with an underlying chain providing consensus, security, and interoperability. Importantly, network states implemented on Nomos allow for social order to emerge and govern their operations, all while preserving critical properties that guarantee individual freedoms for all participants. These include privacy for users and infrastructure providers, censorship resistance, resilience against attacks, and credible neutrality."]}),"\n",(0,i.jsx)(t.p,{children:"In essence, Nomos is the platform that will produce the conditions for true improvements over millennia-old cooperation techniques based on trust and control."}),"\n",(0,i.jsx)(t.p,{children:"The world stands at a crossroads. The greatest minds of this generation are working tirelessly to build the technology that will determine the future of civil rights for centuries to come \u2013 both on the side of coercion, and on the side of freedom. Your decisions now will determine which side emerges victorious."})]})}function h(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}}}]);